/* 3 равные колонки */
grid-template-columns: 1fr 1fr 1fr;

/* первая колонка вдвое шире */
grid-template-columns: 2fr 1fr 1fr;

/* одна колонказанимает всю ширину */
grid-template-columns: 1fr;

.container {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 16px; /* 16px между колонками и строками */
}

/* Разные gap */
.container {
  row-gap: 10px;    /* между строками */
  column-gap: 20px; /* между колонками */
}

/* Без repeat */
grid-template-columns: 1fr 1fr 1fr 1fr;

/* С repeat */
grid-template-columns: repeat(4, 1fr);

/* Повторяющийся паттерн */
grid-template-columns: repeat(3, 100px) 1fr;

.header {
  grid-column: 1 / 4; /* занимает колонки 1-3 (линии 1-4) */
}

.sidebar {
  grid-column: 1 / 2; /* только колонка 1 */
  grid-row: 2 / 4;     /* строки 2-3 */
}

.main {
  grid-column: 2 / 4; /* колонки 2-3 */
  grid-row: 2 / 3;
}

.auto-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
  gap: 16px;
}
